// A minimal mock Nostr relay for evil-09 — node stdlib only (RFC6455
// WebSocket by hand; this repo has no dependencies).
//
// Two virtual relays in one process, seeded from the committed fixtures
// (napps/evil-09-manifest-rollback/fixtures/ — real BIP340-signed kind 35130
// manifests generated by tools/make-evil09-fixtures.mjs):
//
//   /relay-a  the author's write relay — HOSTILE: serves every manifest it
//             has, ignoring the REQ filter (a relay CAN do this; it is
//             exactly what the reference's fetchManifest defends against
//             with its client-side author filter). With ?withhold=1 it also
//             withholds the newest author manifest (v2) — the rollback.
//   /relay-b  a well-behaved napp relay — serves exactly what the filter
//             asks for (its store holds v1 and the attacker clone; only v1
//             matches an author-bound REQ).
//
// Also serves the manifests' file blobs (mini-Blossom): GET /b/<sha256>,
// CORS-open — the harness fetches and sha-verifies them, like fetchBlob.
// Health: GET /health.
//
// Run: node tests/_mockrelay.mjs [port]     (default 9101)
import { createServer } from 'node:http';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const FX = join(root, 'napps', 'evil-09-manifest-rollback', 'fixtures');
const PORT = Number(process.argv[2] || process.env.EVIL_RELAY_PORT || 9101);

const readJson = f => JSON.parse(readFileSync(join(FX, f), 'utf8'));
const v1 = readJson('manifest-v1.json');
const v2 = readJson('manifest-v2.json');
const attacker = readJson('manifest-attacker.json');

const RELAYS = {
  '/relay-a': {
    hostile: true,
    served: () => [v1, v2, attacker],           // ignores the filter entirely
    withheld: () => [v1, attacker],             // + withholds the newest (v2)
  },
  '/relay-b': {
    hostile: false,
    served: () => [v1, attacker],               // filters properly on REQ
    withheld: () => [v1, attacker],
  },
};

function matches(filter, ev) {
  if (filter.kinds && !filter.kinds.includes(ev.kind)) return false;
  if (filter.authors && !filter.authors.includes(ev.pubkey)) return false;
  if (Array.isArray(filter['#d'])) {
    const d = (ev.tags.find(t => t[0] === 'd') || [])[1];
    if (!filter['#d'].includes(d)) return false;
  }
  return true;
}

// ── RFC6455 by hand: server side sends unmasked, client frames are masked ──
const GUID = '258EAFA5-E914-47DA-95CA-C5AB0DC85B11';

function wsFrame(payload) {
  const len = payload.length;
  if (len < 126) return Buffer.from([0x81, len, ...payload]);
  if (len < 65536) {
    const b = Buffer.alloc(4 + len);
    b[0] = 0x81; b[1] = 126; b.writeUInt16BE(len, 2); payload.copy(b, 4);
    return b;
  }
  const b = Buffer.alloc(10 + len);
  b[0] = 0x81; b[1] = 127; b.writeBigUInt64BE(BigInt(len), 2); payload.copy(b, 10);
  return b;
}

function parseFrames(buf, handlers) {
  // one frame per loop; returns the unconsumed remainder
  while (buf.length >= 2) {
    const b0 = buf[0], b1 = buf[1];
    const opcode = b0 & 0x0f;
    const masked = !!(b1 & 0x80);
    let len = b1 & 0x7f;
    let off = 2;
    if (len === 126) {
      if (buf.length < 4) break;
      len = buf.readUInt16BE(2); off = 4;
    } else if (len === 127) {
      if (buf.length < 10) break;
      len = Number(buf.readBigUInt64BE(2)); off = 10;
    }
    if (masked) {
      if (buf.length < off + 4 + len) break;
      const mask = buf.slice(off, off + 4);
      const payload = Buffer.from(buf.slice(off + 4, off + 4 + len)); // copy
      for (let i = 0; i < payload.length; i++) payload[i] ^= mask[i % 4];
      buf = buf.slice(off + 4 + len);
      handlers.frame(opcode, payload);
    } else {
      if (buf.length < off + len) break;
      const payload = buf.slice(off, off + len);
      buf = buf.slice(off + len);
      handlers.frame(opcode, payload);
    }
  }
  return buf;
}

const server = createServer((req, res) => {
  if (req.url === '/health') {
    res.writeHead(200).end('ok');
    return;
  }
  const m = /^\/b\/([0-9a-f]{64})$/.exec(req.url || '');
  if (m) {
    try {
      const blob = readFileSync(join(FX, 'blobs', m[1]));
      res.writeHead(200, {
        'content-type': 'application/octet-stream',
        'access-control-allow-origin': '*',
      }).end(blob);
    } catch (_) {
      res.writeHead(404).end('no such blob');
    }
    return;
  }
  res.writeHead(404).end('mock relay: /relay-a /relay-b (ws) · /b/<sha> (blobs) · /health');
});

server.on('upgrade', (req, socket) => {
  const url = new URL(req.url || '/', 'http://localhost');
  const relay = RELAYS[url.pathname];
  if (!relay) { socket.destroy(); return; }
  const withhold = url.searchParams.get('withhold') === '1';
  const key = req.headers['sec-websocket-key'];
  if (!key) { socket.destroy(); return; }
  const accept = createHash('sha1').update(key + GUID).digest('base64');
  socket.write(
    'HTTP/1.1 101 Switching Protocols\r\n' +
    'Upgrade: websocket\r\n' +
    'Connection: Upgrade\r\n' +
    'Sec-WebSocket-Accept: ' + accept + '\r\n\r\n'
  );
  socket.setNoDelay(true);

  const send = (arr) => socket.write(wsFrame(Buffer.from(JSON.stringify(arr))));
  let buf = Buffer.alloc(0);
  socket.on('data', (chunk) => {
    buf = parseFrames(Buffer.concat([buf, chunk]), {
      frame(opcode, payload) {
        if (opcode === 0x8) { // close
          try { socket.write(Buffer.from([0x88, 0])); } catch (_) {}
          socket.end();
          return;
        }
        if (opcode === 0x9) { // ping → pong
          socket.write(Buffer.from([0x8a, payload.length, ...payload]));
          return;
        }
        if (opcode !== 0x1) return; // text only
        let msg;
        try { msg = JSON.parse(payload.toString()); } catch (_) { return; }
        if (!Array.isArray(msg)) return;
        if (msg[0] === 'REQ') {
          const sub = msg[1];
          const filter = msg[2] || {};
          const all = withhold ? relay.withheld() : relay.served();
          const served = relay.hostile ? all : all.filter(e => matches(filter, e));
          for (const ev of served) send(['EVENT', sub, ev]);
          send(['EOSE', sub]);
        } else if (msg[0] === 'CLOSE') {
          // one-shot lookups: nothing to keep
        }
      },
    });
  });
  socket.on('error', () => {});
});

server.listen(PORT, () => {
  console.log('evil-09 mock relay on ws://localhost:' + PORT + '/relay-a (hostile' +
    (process.argv.includes('--withhold') ? ', withholding' : '') + ') and /relay-b (well-behaved); blobs at /b/<sha>; health at /health');
});
